const API_URL = "https://miniai-api.dallasaristarchos.workers.dev/api/chat";
const RATING_API_URL = API_URL.replace("/api/chat", "/api/ratings");
const RATING_CLIENT_KEY = "miniai.v2.ratingClientId";
let selectedRating = 0;
const STORAGE_KEY = "miniai.v2.conversations";
const ACTIVE_KEY = "miniai.v2.activeConversation";
const SETTINGS_KEY = "miniai.v2.settings";
const DEFAULT_SETTINGS = {voiceStyle:"female",voiceURI:"",speechRate:1,speechPitch:1,speechVolume:1,autoSpeak:false,typingSpeed:30,chatTextSize:14,enterToSend:true,assistantName:"MiniAI",responseLength:"balanced",plugins:{calculator:true,weather:true,currency:true,wikipedia:true,webSearch:true,dictionary:true,books:true,units:true}};
let prefs = (()=>{try{const saved=JSON.parse(localStorage.getItem(SETTINGS_KEY)||"{}");return {...DEFAULT_SETTINGS,...saved,plugins:{...DEFAULT_SETTINGS.plugins,...(saved.plugins||{})}}}catch{return {...DEFAULT_SETTINGS,plugins:{...DEFAULT_SETTINGS.plugins}}}})();
function saveSettings(){try{localStorage.setItem(SETTINGS_KEY,JSON.stringify(prefs))}catch{}}

const $ = (selector) => document.querySelector(selector);
const form = $("#chatForm"), input = $("#messageInput"), conversation = $("#conversation");
const messagesEl = $("#messages"), sendButton = $("#sendButton");
let chats = loadChats(), activeId = localStorage.getItem(ACTIVE_KEY);
let busy = false, toastTimer;
let voiceCallActive=false, voiceSpeaking=false, callRecognition=null, dictationRecognition=null;
let pendingFiles = [];
const MAX_FILE_BYTES = 5 * 1024 * 1024;
const TEXT_EXTENSIONS = new Set(["txt","md","csv","json","js","ts","jsx","tsx","py","html","css","xml","yaml","yml","log"]);

function uid(){return globalThis.crypto?.randomUUID?.() || `chat-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;}
function loadChats(){try{const value=JSON.parse(localStorage.getItem(STORAGE_KEY)||"[]");return Array.isArray(value)?value.filter(c=>c&&c.id&&Array.isArray(c.messages)):[]}catch{return []}}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(chats));if(activeId)localStorage.setItem(ACTIVE_KEY,activeId)}catch{showToast("Storage is full. Export an older chat to keep it safe.")}}
function currentChat(){return chats.find(c=>c.id===activeId)}
function makeChat(mode="general"){const chat={id:uid(),title:mode==="coding"?"New coding chat":"New conversation",mode,updatedAt:Date.now(),messages:[]};chats.unshift(chat);activeId=chat.id;save();renderAll();input.focus();closeSidebar();}
function showToast(message){const el=$("#toast");el.textContent=message;el.classList.add("visible");clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove("visible"),2300)}
function getRatingClientId(){try{let id=localStorage.getItem(RATING_CLIENT_KEY);if(!id){id=globalThis.crypto?.randomUUID?.()||`rating-${Date.now()}-${Math.random().toString(36).slice(2,12)}`;localStorage.setItem(RATING_CLIENT_KEY,id)}return id}catch{return `rating-${Date.now()}-${Math.random().toString(36).slice(2,12)}`}}
function paintRatingStars(){document.querySelectorAll("[data-rating]").forEach(button=>{const value=Number(button.dataset.rating);button.classList.toggle("selected",value<=selectedRating);button.setAttribute("aria-pressed",String(value===selectedRating))})}
async function loadRatingSummary(){const summary=$("#ratingSummary");if(!summary)return;try{const response=await fetch(RATING_API_URL,{method:"GET",cache:"no-store",headers:{Accept:"application/json"}});if(!response.ok)throw new Error("Unavailable");const data=await response.json();summary.textContent=data.count?`${Number(data.average).toFixed(1)} / 5 · ${Number(data.count).toLocaleString()} ${data.count===1?"rating":"ratings"}`:"Be the first to rate MiniAI."}catch{summary.textContent="Community rating is temporarily unavailable."}}
function bindRatingUI(){const stars=document.querySelectorAll("[data-rating]");const submit=$("#submitRating");const feedback=$("#ratingFeedback");const status=$("#ratingStatus");try{const saved=Number(localStorage.getItem("miniai.v2.myRating"));if(Number.isInteger(saved)&&saved>=1&&saved<=5)selectedRating=saved}catch{}paintRatingStars();stars.forEach(button=>button.addEventListener("click",()=>{selectedRating=Number(button.dataset.rating);paintRatingStars();if(submit)submit.disabled=false;if(status)status.textContent=`You selected ${selectedRating} out of 5 stars.`}));submit?.addEventListener("click",async()=>{if(!selectedRating){if(status)status.textContent="Choose a star rating first.";return}submit.disabled=true;if(status)status.textContent="Sending your rating…";try{const response=await fetch(RATING_API_URL,{method:"POST",headers:{"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify({clientId:getRatingClientId(),rating:selectedRating,feedback:feedback?.value.trim().slice(0,500)||""})});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||"Couldn't save your rating.");try{localStorage.setItem("miniai.v2.myRating",String(selectedRating))}catch{}if(feedback)feedback.value="";if(status)status.textContent="Thanks! Your rating has been saved.";await loadRatingSummary()}catch(error){if(status)status.textContent=error.message||"Couldn't save your rating. Please try again."}finally{submit.disabled=!selectedRating}})}

function escapeHTML(value){return String(value).replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]));}
function safeLink(url){try{const parsed=new URL(url);return ["https:","http:"].includes(parsed.protocol)?parsed.href:null}catch{return null}}
function inlineMarkdown(value){let out=escapeHTML(value);out=out.replace(/`([^`]+)`/g,"<code>$1</code>");out=out.replace(/\*\*(.+?)\*\*/g,"<strong>$1</strong>").replace(/(?<!\*)\*([^*\n]+)\*(?!\*)/g,"<em>$1</em>");out=out.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,(all,label,url)=>{const safe=safeLink(url);return safe?`<a href="${escapeHTML(safe)}" target="_blank" rel="noopener noreferrer">${label}</a>`:label});out=out.replace(/(^|\s)(https?:\/\/[^\s<]+)/g,(all,space,url)=>{const clean=url.replace(/[.,!?;:]+$/g,"");const safe=safeLink(clean);return safe?`${space}<a href="${escapeHTML(safe)}" target="_blank" rel="noopener noreferrer">${escapeHTML(clean)}</a>${url.slice(clean.length)}`:all});return out}
function markdownHTML(text){const chunks=String(text).split(/```([\s\S]*?)```/g);return chunks.map((chunk,index)=>{if(index%2===1){const lines=chunk.replace(/^\n|\n$/g,"").split("\n");let lang="code";if(lines.length&&/^[a-zA-Z0-9_+-]{1,20}$/.test(lines[0].trim()))lang=lines.shift().trim();const code=lines.join("\n");return `<div class="code-wrap"><div class="code-head"><span>${escapeHTML(lang)}</span><button class="code-copy" type="button" data-action="copy-code">Copy code</button></div><pre>${escapeHTML(code)}</pre></div>`;}const lines=chunk.split("\n");let html="",listType=null;const closeList=()=>{if(listType){html+=`</${listType}>`;listType=null}};for(const line of lines){const trimmed=line.trim();const bullet=trimmed.match(/^[-*]\s+(.+)/),number=trimmed.match(/^\d+[.)]\s+(.+)/);if(bullet||number){const type=bullet?"ul":"ol";if(listType!==type){closeList();html+=`<${type}>`;listType=type}html+=`<li>${inlineMarkdown((bullet||number)[1])}</li>`;continue}closeList();if(!trimmed){html+="<br>";continue}const heading=trimmed.match(/^#{1,3}\s+(.+)/);if(heading){html+=`<p><strong>${inlineMarkdown(heading[1])}</strong></p>`;continue}if(trimmed.startsWith("> ")){html+=`<blockquote>${inlineMarkdown(trimmed.slice(2))}</blockquote>`;continue}html+=`<p>${inlineMarkdown(line)}</p>`;}closeList();return html;}).join("")}
function renderMessage(message){const row=document.createElement("article");row.className=`message ${message.role}`;row.__messageText=message.content;row.__failed=Boolean(message.failed);const avatar=document.createElement("div");avatar.className="avatar";avatar.textContent=message.role==="user"?"Y":(String(prefs.assistantName||"MiniAI").trim().charAt(0).toUpperCase()||"M");avatar.setAttribute("aria-hidden","true");const content=document.createElement("div");content.className="message-content";if(message.role!=="user"){const author=document.createElement("div");author.className="message-author";author.textContent=prefs.assistantName||"MiniAI";content.append(author)}const bubble=document.createElement("div");bubble.className="bubble";bubble.innerHTML=markdownHTML(message.content);content.append(bubble);const actions=document.createElement("div");actions.className="message-actions";const copy=document.createElement("button");copy.type="button";copy.dataset.action="copy-message";copy.textContent="Copy";actions.append(copy);if(message.failed){const retry=document.createElement("button");retry.type="button";retry.dataset.action="retry";retry.textContent="Try again";actions.append(retry)}content.append(actions);row.append(avatar,content);return row;}
function renderHistory(){const list=$("#historyList"),query=$("#historySearch").value.trim().toLowerCase();list.replaceChildren();const visible=[...chats].sort((a,b)=>b.updatedAt-a.updatedAt).filter(c=>!query||c.title.toLowerCase().includes(query)||c.messages.some(m=>m.content.toLowerCase().includes(query)));if(!visible.length){const empty=document.createElement("div");empty.className="history-empty";empty.textContent=query?"No matching conversations.":"Your conversations will appear here.";list.append(empty);return}for(const chat of visible){const item=document.createElement("div");item.className=`history-item${chat.id===activeId?" active":""}${chat.mode==="coding"?" coding-history-item":""}`;item.tabIndex=0;item.setAttribute("role","button");item.setAttribute("aria-label",`Open ${chat.title}`);const icon=document.createElement("span");icon.className="history-icon";icon.textContent="◷";const title=document.createElement("span");title.className="history-title";title.textContent=chat.title;const del=document.createElement("button");del.className="history-delete";del.type="button";del.dataset.deleteChat=chat.id;del.setAttribute("aria-label",`Delete ${chat.title}`);del.textContent="×";if(chat.mode==="coding"){const tag=document.createElement("span");tag.className="history-code-tag";tag.textContent="CODE";item.append(icon,title,tag,del)}else item.append(icon,title,del);item.addEventListener("click",e=>{if(e.target.closest("[data-delete-chat]"))return;activeId=chat.id;save();renderAll();closeSidebar()});item.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();activeId=chat.id;save();renderAll();closeSidebar()}});list.append(item)}}
function renderConversation(){const chat=currentChat();messagesEl.replaceChildren();const welcome=$("#welcome");const hasMessages=Boolean(chat?.messages.length);welcome.hidden=hasMessages;if(chat)chat.messages.forEach(message=>messagesEl.append(renderMessage(message)));conversation.scrollTop=conversation.scrollHeight;}
function renderAll(){renderHistory();renderConversation();const chat=currentChat();const badge=$("#chatModeBadge");if(badge)badge.hidden=chat?.mode!=="coding";document.body.classList.toggle("coding-chat-active",chat?.mode==="coding")}
function titleFrom(text){const clean=text.replace(/\s+/g," ").trim();return clean.length>34?clean.slice(0,34).trim()+"…":clean||"New conversation"}
function setBusy(value){busy=value;sendButton.disabled=value;sendButton.innerHTML=value?"<span>…</span>":"<span>↑</span>";sendButton.setAttribute("aria-label",value?"Waiting for MiniAI":"Send message")}
function appendMessage(role,content,extra={}){const chat=currentChat();if(!chat)return null;const message={role,content,createdAt:Date.now(),...extra};chat.messages.push(message);chat.updatedAt=Date.now();if(role==="user"&&chat.title==="New conversation")chat.title=titleFrom(content);save();renderAll();return message}
function showTyping(status="Thinking through your question…"){const row=document.createElement("article");row.className="message";row.id="typingIndicator";row.innerHTML=`<div class="avatar" aria-hidden="true">${escapeHTML((prefs.assistantName||"MiniAI").trim().charAt(0).toUpperCase()||"M")}</div><div class="message-content"><div class="message-author">${escapeHTML(prefs.assistantName||"MiniAI")}</div><div class="bubble"><span class="typing" aria-label="${escapeHTML(prefs.assistantName||"MiniAI")} is working"><i></i><i></i><i></i></span><span class="work-status" style="display:block;margin-top:7px;color:#c7a2f3;font-size:11px;letter-spacing:.2px">${escapeHTML(status)}</span></div></div>`;messagesEl.append(row);conversation.scrollTop=conversation.scrollHeight}
function needsWebResearch(text){return /\b(latest|today|current|currently|202[5-9]|price|prices|cost|buy|budget|best|compare|review|release|news|weather|available|availability|specs|specifications|benchmark|deal|where can i|search|research|recommend|recommendation|pc build|gaming pc|gpu|cpu|motherboard|laptop|phone|market|version)\b/i.test(text)}
function cleanHistory(){return (currentChat()?.messages||[]).filter(m=>!m.failed&&["user","assistant"].includes(m.role)).slice(-12).map(m=>({role:m.role,content:m.content}))}
function fileExtension(name){return (String(name).split(".").pop()||"").toLowerCase()}
function renderPendingFiles(){const list=$("#attachmentList");list.replaceChildren();pendingFiles.forEach((file,index)=>{const item=document.createElement("div");item.className="attachment-chip";if(file.kind==="image"){const preview=document.createElement("img");preview.className="attachment-thumb";preview.src=file.dataUrl;preview.alt="Photo attachment preview";item.append(preview)}const name=document.createElement("span");name.textContent=(file.kind==="image"?"Photo · ":"File · ")+file.name;const remove=document.createElement("button");remove.type="button";remove.textContent="×";remove.setAttribute("aria-label","Remove "+file.name);remove.addEventListener("click",()=>{pendingFiles.splice(index,1);renderPendingFiles()});item.append(name,remove);list.append(item)})}
async function imageToDataUrl(file){if(file.type==="image/gif"){if(file.size>4.7*1024*1024)throw new Error("GIF is too large to send. Choose a smaller image.");return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}if(typeof createImageBitmap!=="function"){if(file.size>4.7*1024*1024)throw new Error("This browser can't compress this large photo. Try a smaller image or Chrome.");return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}const bitmap=await createImageBitmap(file);const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext("2d");ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();let blob=await new Promise(resolve=>canvas.toBlob(resolve,"image/jpeg",.84));if(!blob)throw new Error("Could not prepare this photo.");if(blob.size>4.7*1024*1024){const scale2=Math.sqrt((4.7*1024*1024)/blob.size)*.92;const smaller=document.createElement("canvas");smaller.width=Math.max(1,Math.round(canvas.width*scale2));smaller.height=Math.max(1,Math.round(canvas.height*scale2));smaller.getContext("2d").drawImage(canvas,0,0,smaller.width,smaller.height);blob=await new Promise(resolve=>smaller.toBlob(resolve,"image/jpeg",.76))}if(!blob||blob.size>4.7*1024*1024)throw new Error("This photo is still too large. Try a smaller picture.");return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob)})}
async function readSelectedFiles(fileList){let added=0;for(const file of Array.from(fileList||[])){try{if(file.type.startsWith("image/")){if(file.size>15*1024*1024){showToast(file.name+" is over the 15 MB photo limit.");continue}const dataUrl=await imageToDataUrl(file);pendingFiles.push({name:file.name||"camera-photo.jpg",mimeType:dataUrl.startsWith("data:image/png")?"image/png":dataUrl.startsWith("data:image/gif")?"image/gif":"image/jpeg",kind:"image",dataUrl});added++}else if(file.size>MAX_FILE_BYTES){showToast(file.name+" is over the 5 MB file limit.");continue}else if(TEXT_EXTENSIONS.has(fileExtension(file.name))){const content=await file.text();pendingFiles.push({name:file.name,mimeType:file.type||"text/plain",kind:"text",content:content.slice(0,30000)});added++}else if(fileExtension(file.name)==="pdf"){if(!window.pdfjsLib){showToast("PDF reader did not load. Try a TXT version.");continue}const pdf=await window.pdfjsLib.getDocument({data:await file.arrayBuffer()}).promise;let pages=[];for(let pageNo=1;pageNo<=Math.min(pdf.numPages,20);pageNo++){const page=await pdf.getPage(pageNo);const content=await page.getTextContent();pages.push(content.items.map(item=>item.str).join(" "))}pendingFiles.push({name:file.name,mimeType:"application/pdf",kind:"text",content:pages.join("\n\n").slice(0,30000)});added++}else showToast("That file type isn't supported yet: "+file.name)}catch(error){showToast(error.message||("Couldn't read "+file.name))}}renderPendingFiles();return added}

async function askMiniAI(attachments=[]){const chat=currentChat();if(!chat)return;const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),90000);const lastUser=currentChat()?.messages?.filter(m=>m.role==="user").at(-1)?.content||"";const searching=needsWebResearch(lastUser)||/https?:\/\//i.test(lastUser);showTyping(searching?"Checking sources, then writing…":attachments.length?"Reviewing your files…":"Thinking through your question…");try{const response=await fetch(API_URL,{method:"POST",mode:"cors",cache:"no-store",headers:{"Content-Type":"application/json"},body:JSON.stringify({messages:cleanHistory(),attachments,mode:currentChat()?.mode||"general",assistantName:prefs.assistantName,responseLength:prefs.responseLength,plugins:prefs.plugins}),signal:controller.signal});if(!response.ok){const data=await response.json().catch(()=>({}));const error=new Error(data.error||`MiniAI service error (${response.status}).`);error.status=response.status;throw error}const typing=$("#typingIndicator");let live=null,row=null,bubble=null,streamText=null;const beginVisibleReply=()=>{if(live)return;typing?.remove();live={role:"assistant",content:"",createdAt:Date.now()};const chatNow=currentChat();if(!chatNow)throw new Error("This conversation is no longer open.");chatNow.messages.push(live);chatNow.updatedAt=Date.now();row=renderMessage(live);messagesEl.append(row);bubble=row.querySelector(".bubble");streamText=document.createTextNode("");bubble.classList.add("streaming");bubble.replaceChildren(streamText)};const reader=response.body?.getReader();if(!reader)throw new Error("Streaming is not supported by this browser.");const decoder=new TextDecoder();let buffer="";const acceptEvent=payload=>{if(!payload||payload==="[DONE]")return;const event=JSON.parse(payload);if(event.error)throw new Error(event.error);const delta=typeof event.response==="string"?event.response:(typeof event.choices?.[0]?.delta?.content==="string"?event.choices[0].delta.content:"");if(delta){beginVisibleReply();live.content+=delta;streamText.data+=delta;conversation.scrollTop=conversation.scrollHeight}};while(true){const {value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});const lines=buffer.split("\n");buffer=lines.pop()||"";for(const line of lines){if(!line.startsWith("data:"))continue;const payload=line.slice(5).trim();if(!payload)continue;try{acceptEvent(payload)}catch(error){if(error instanceof SyntaxError)continue;throw error}}}buffer+=decoder.decode();if(buffer.trim().startsWith("data:")){const payload=buffer.trim().slice(5).trim();if(payload)try{acceptEvent(payload)}catch(error){if(!(error instanceof SyntaxError))throw error}}if(!live?.content.trim())throw new Error("MiniAI finished without sending answer text. Please try again.");bubble.classList.remove("streaming");bubble.innerHTML=markdownHTML(live.content);save();renderHistory();if(voiceCallActive||prefs.autoSpeak)speakReply(live.content);}catch(error){$("#typingIndicator")?.remove();let message=error.name==="AbortError"?"MiniAI took too long to respond. Please try again.":error.status===429?"MiniAI is receiving too many requests. Wait a minute and try again.":error instanceof TypeError?"MiniAI couldn't reach its server. Check your connection and try again.":(error.message||"Something went wrong. Please try again.");appendMessage("assistant",message,{failed:true});}finally{clearTimeout(timeout);setBusy(false);if(voiceCallActive&&!voiceSpeaking&&!window.speechSynthesis?.speaking)setTimeout(startCallListening,500)}}
async function sendMessage(text){const value=String(text||"").trim();if((!value&&!pendingFiles.length)||busy)return;if(!currentChat())makeChat();const files=pendingFiles.splice(0);const fileSummary=files.map(f=>`[Attached ${f.kind}: ${f.name}]`).join(" ");appendMessage("user",[value,fileSummary].filter(Boolean).join("\n"));input.value="";input.style.height="auto";renderPendingFiles();setBusy(true);await askMiniAI(files)}
function retryLast(){if(busy)return;const chat=currentChat();if(!chat)return;const last=chat.messages.at(-1);if(last?.failed)chat.messages.pop();else if(chat.messages.at(-1)?.role!=="user")return;save();renderAll();setBusy(true);askMiniAI()}
function resetCurrentChat(){const chat=currentChat();if(!chat)return;chat.messages=[];chat.title="New conversation";chat.updatedAt=Date.now();save();renderAll();input.focus();showToast("Conversation cleared")}
function deleteChat(id){const index=chats.findIndex(c=>c.id===id);if(index<0)return;chats.splice(index,1);if(activeId===id){activeId=chats[0]?.id||null;if(!activeId){makeChat();return}}save();renderAll();showToast("Conversation deleted")}
function exportChat(){const chat=currentChat();if(!chat||!chat.messages.length){showToast("There is no conversation to export yet");return}const body=chat.messages.map(m=>`${m.role==="user"?"You":"MiniAI"}\n${m.content}`).join("\n\n────────────────────\n\n");const blob=new Blob([`MiniAI — ${chat.title}\n\n${body}`],{type:"text/plain;charset=utf-8"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=`miniai-${chat.title.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"")||"conversation"}.txt`;a.click();URL.revokeObjectURL(url);showToast("Conversation exported")}
function openSidebar(){$("#sidebar").classList.add("open");$("#sidebarScrim").classList.add("visible");$("#mobileMenu").setAttribute("aria-expanded","true")}
function closeSidebar(){$("#sidebar").classList.remove("open");$("#sidebarScrim").classList.remove("visible");$("#mobileMenu").setAttribute("aria-expanded","false")}
async function checkConnection(){const dot=$("#connectionDot"),side=$("#sidebarStatus"),label=$("#connectionLabel");try{const response=await fetch(API_URL.replace("/api/chat","/health"),{cache:"no-store"});const data=await response.json();const online=response.ok&&data.ok;dot.classList.toggle("offline",!online);side.classList.toggle("offline",!online);label.textContent=online?"MiniAI 2.0":"Reconnecting";side.title=online?"API reachable":"API unavailable"}catch{dot.classList.add("offline");side.classList.add("offline");label.textContent="MiniAI 2.0";side.title="Connection check failed"}}

form.addEventListener("submit",event=>{event.preventDefault();sendMessage(input.value)});
const attachButton=$("#attachButton"),attachMenu=$("#attachMenu");
function closeAttachMenu(){attachMenu.hidden=true;attachButton.setAttribute("aria-expanded","false")}
attachButton.addEventListener("click",()=>{attachMenu.hidden=!attachMenu.hidden;attachButton.setAttribute("aria-expanded",String(!attachMenu.hidden));if(!attachMenu.hidden&&window.matchMedia("(max-width:760px)").matches){const r=attachButton.getBoundingClientRect();attachMenu.style.setProperty("--attach-menu-bottom",`${Math.max(12,window.innerHeight-r.top+8)}px`);const left=Math.max(12,Math.min(r.left,window.innerWidth-222));attachMenu.style.left=`${left}px`}});
attachMenu.addEventListener("click",event=>{const choice=event.target.closest("[data-pick]");if(!choice)return;const picker={files:"#fileInput",camera:"#cameraInput",gallery:"#galleryInput"}[choice.dataset.pick];closeAttachMenu();$(picker).click()});
["#fileInput","#folderInput","#galleryInput"].forEach(selector=>$(selector).addEventListener("change",async event=>{await readSelectedFiles(event.target.files);event.target.value=""}));$("#cameraInput").addEventListener("change",async event=>{const count=await readSelectedFiles(event.target.files);event.target.value="";if(count>0)await sendMessage(input.value.trim()||"Please analyse this photo.")});
input.addEventListener("input",()=>{input.style.height="auto";input.style.height=Math.min(input.scrollHeight,150)+"px"});
input.addEventListener("keydown",event=>{if(event.key==="Enter"&&!event.shiftKey&&prefs.enterToSend){event.preventDefault();form.requestSubmit()}});
$("#newChat").addEventListener("click",()=>makeChat("general"));$("#newCodeChat").addEventListener("click",()=>{makeChat("coding");showToast("Coding workspace ready")});$("#mobileMenu").addEventListener("click",openSidebar);$("#closeSidebar").addEventListener("click",closeSidebar);$("#sidebarScrim").addEventListener("click",closeSidebar);$("#clearChat").addEventListener("click",resetCurrentChat);$("#exportChat").addEventListener("click",exportChat);
$("#searchToggle").addEventListener("click",()=>{$("#historySearchWrap").classList.toggle("visible");if($("#historySearchWrap").classList.contains("visible"))$("#historySearch").focus();else{$("#historySearch").value="";renderHistory()}});
